#include <stdio.h>



int main(void) {
    int a[15], x, left = 0, right = 14, answer = -1;
    for (int i = 0; i < 15; i++) scanf("%d", &a[i]);
    scanf("%d", &x);
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (a[mid] == x) { answer = mid; break; }
        if (a[mid] < x) left = mid + 1;
        else right = mid - 1;
    }
    printf("%d\n", answer);
    return 0;
}
